function countFittingSubsets(nums: number[], target: number): number {
  const n = nums.length;
  let count = 0;
  for (let mask = 1; mask < 1 << n; mask++) {
    let lo = Infinity, hi = -Infinity;
    for (let i = 0; i < n; i++)
      if (mask & (1 << i)) { lo = Math.min(lo, nums[i]); hi = Math.max(hi, nums[i]); }
    if (lo + hi <= target) count++;
  }
  return count % 1000000007;
}

