class Solution:
    def countFittingSubsets(self, nums: List[int], target: int) -> int:
        n, count = len(nums), 0
        for mask in range(1, 1 << n):
            picked = [nums[i] for i in range(n) if mask >> i & 1]
            if min(picked) + max(picked) <= target:
                count += 1
        return count % 1000000007

