function countFittingSubsets(nums: number[], target: number): number {
  const MOD = 1000000007;
  const a = [...nums].sort((x, y) => x - y);
  const n = a.length;
  const pow2 = new Array(n).fill(1);
  for (let k = 1; k < n; k++) pow2[k] = (pow2[k - 1] * 2) % MOD;
  let lo = 0, hi = n - 1, count = 0;
  while (lo <= hi) {
    if (a[lo] + a[hi] <= target) {
      count = (count + pow2[hi - lo]) % MOD;
      lo++;
    } else hi--;
  }
  return count;
}

